function demoMain(idx,label){
  var pols=[["admin","*","ALLOW"],["dev","db.read","ALLOW"],["guest","db.write","DENY"]];
  var p=pols[idx%pols.length];
  return "["+label+"] role '"+p[0]+"' on '"+p[1]+"' => "+p[2];
}

